list_shipping_rates.code:
import (
	"fmt"
)

resp, err := client.ShippingRates().ListShippingRates(ctx, map[string]any{
	"method":        "flat_rate",
	"handling_cost": "with_handling",
	"sort":          "name",
	"order":         "asc",
}, nil)
if err != nil {
	log.Fatal(err)
}
body := resp.Map().(map[string]any)
for _, row := range body["shipping_rates"].([]any) {
	rate := row.(map[string]any)
	fmt.Println(rate["id"], rate["name"], rate["method"], rate["shipping_cost"])
}
pagination := body["pagination"].(map[string]any)
fmt.Println(pagination["total"], pagination["has_next"])

